#!/usr/bin/env python3
"""R2 independent rubric evaluator for Delta Tau Delta."""
import json, math
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3]
AUDIT=ROOT/'audit'/'delta_tau_delta_e06b0b5'
def xy(lon,lat):
    return ((lon+86.9137)*111412.84*math.cos(math.radians(40.4274)),(lat-40.4274)*111040.0)
def evaluate():
    reopen=json.loads((AUDIT/'independent_grade_r2'/'reopen_inspection.json').read_text(encoding='utf-8-sig'))
    gis=json.loads((AUDIT/'sources'/'indiana_lidar_building_footprint_oid409940_2026-10-26.json').read_text(encoding='utf-8-sig'))
    ring=gis['features'][0]['geometry']['rings'][0][:-1]
    expected=[xy(lon,lat) for lon,lat in ring]
    actual=[(v[0],v[1]) for v in reopen['structural_body']['world_vertices_xyz'] if abs(v[2])<1e-5]
    d=max([min(math.dist(p,q) for q in actual) for p in expected]+[min(math.dist(q,p) for p in expected) for q in actual])
    criteria=[
      {'criterion':'Correct identity and source-backed footprint','points':2.0,'max_points':2,'evidence':f"Downloaded and directly inspected the cited Purdue_Delts profile image (400x400 px, https://unavatar.io/x/Purdue_Delts, retrieval 2026-10-26): the sign identifies Delta Tau Delta, Gamma Lambda, 400 Northwestern; the house appears in that image. Transformed 2018 GIS feature 409940's six unique vertices match the reopened structural base ring with symmetric max nearest-vertex error {d:.6f} m. The GIS feature itself is unlabeled and the address point is just outside it, but the image/sign plus zoning/chapter documents resolve identity.",'finding':'Identity and footprint are adequately supported, with GIS collection/parcel uncertainty retained.'},
      {'criterion':'Position, orientation, and scale/dimensions','points':2.0,'max_points':2,'evidence':'Reopened structural shell XY bounds match the projected LiDAR ring and retain the expected campus-world coordinates; no horizontal displacement, rotation, or scale discrepancy found.','finding':'No material discrepancy.'},
      {'criterion':'Evidence-backed height, floors, and roof form','points':1.0,'max_points':2,'evidence':'The directly inspected profile image supports a broad steep, front-gabled roof silhouette and chimney-like verticals. Its snowy, low-resolution crop cannot establish eaves/ridge height, floor count, pitch, or exact roof/chimney layout. Modeled 10.4 m eaves, 15.2 m ridge, 17.4 m tops, and three floor/window bands remain estimates.','finding':'Vertical dimensions and floor count remain unsupported; retain explicit estimate labels.'},
      {'criterion':'Facade, entrances, and distinctive architecture','points':1.5,'max_points':2,'evidence':'The cited profile image directly supports red brick, multiple front-facing gables, rectangular window rows, a steep roof and an arched masonry entrance. The updated asset now includes three projecting front gables, repeated windows, brick and a schematic arched/pointed entry. The partial oblique snowy image does not verify the full elevations, exact bay count/spacing, facade entry side, or the 1970 addition seam.','finding':'Broad facade character is now evidence-backed; most exact layout remains schematic.'},
      {'criterion':'Modular export, portability, and complete evidence','points':1.75,'max_points':2,'evidence':f"Blender {reopen['blender_version']} reopened the saved asset and expected scene/collection. Target collection contains {reopen['object_count']} objects; zero modifiers and zero external libraries. Three default objects (Cube, Camera, Light) remain outside the target collection. Source/build evidence and both previews exist. The three-quarter view is usable; plan preview remains vertically clipped and roof-dominated. The shared manifest still lists 1 object and old bounds, although the asset is now {reopen['object_count']} objects with current expanded bounds.",'finding':'Portable named collection is ready. Correct the plan view and refresh the coordinator-owned manifest before integration.'}
    ]
    return {'score':round(sum(x['points'] for x in criteria),2),'max_score':10,'criteria':criteria,'evidence':{'asset_sha256':reopen['sha256'],'asset_path':'modular/buildings/massing_delta_tau_delta_e06b0b5.blend','blender_version':reopen['blender_version'],'scene':reopen['scene'],'collection_object_count':reopen['object_count'],'scene_object_count':reopen['scene_object_count'],'bounds_world_m':reopen['bounds_world_m'],'external_libraries':reopen['external_libraries'],'modifiers_total':reopen['modifiers_total'],'gis_footprint_max_vertex_error_m':round(d,8),'identity_visual_source':'https://unavatar.io/x/Purdue_Delts (proxy for cited Purdue_Delts X profile avatar; directly inspected; 400x400 px; retrieved 2026-10-26)','plan_preview':'Still cropped in north/south direction; not an effective full footprint view.','manifest_mismatch':'manifest object_count=1 and old bounds do not match current asset. Shared coordinator-owned metadata, excluded from the asset score but must be corrected before integration.'},'findings':['PASS at 8.25/10.','The profile image substantially strengthens identity and broad facade support but cannot establish measured height/floors or exact facade geometry.','The stale manifest does not reduce the building asset score because it is shared coordinator-owned metadata, but it is a concrete integration blocker until updated.','Plan preview remains clipped; default Cube, Camera and Light are present in the Blender scene outside the export collection.']}
if __name__=='__main__':
    result=evaluate()
    dest=ROOT/'audit'/'delta_tau_delta_e06b0b5'/'independent_grade_r2'/'result.json'
    dest.write_text(json.dumps(result,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
    print(json.dumps(result,indent=2,ensure_ascii=False))
